use ingot::Default
use ingot::Fn
use ingot::Functor
use ingot::Applicative
use ingot::Monad
use ingot::Result
use ingot::panic

pub enum Option<T> {
    Some(T),
    None
}

impl<T> Option<T> {
    pub fn is_some(own self) -> bool {
        match self {
            Self::Some(_) => true
            Self::None => false
        }
    }

    pub fn is_none(own self) -> bool {
        !self.is_some()
    }

    pub fn map<U, F: Fn<T, U>>(own self, _ func: F) -> Option<U> {
        match self {
            Self::Some(value) => Option::Some(func.call(value))
            Self::None => Option::None
        }
    }

    pub fn and_then<U, F: Fn<T, Option<U>>>(own self, _ func: F) -> Option<U> {
        match self {
            Self::Some(value) => func.call(value)
            Self::None => Option::None
        }
    }

    pub fn ok_or<E>(own self, _ err: own E) -> Result<E, T> {
        match self {
            Self::Some(value) => Result::Ok(value)
            Self::None => Result::Err(err)
        }
    }

    pub fn ok_or_else<E, F: Fn<(), E>>(own self, _ err_func: F) -> Result<E, T> {
        match self {
            Self::Some(value) => Result::Ok(value)
            Self::None => Result::Err(err_func.call(()))
        }
    }

    pub fn unwrap(own self) -> T {
        match self {
            Self::Some(t) => t
            Self::None => panic()
        }
    }

    pub fn unwrap_or(own self, default: own T) -> T {
        match self {
            Self::Some(x) => x
            Self::None => default
        }
    }

    pub fn unwrap_or_else<F: Fn<(), T>>(own self, _ default_func: F) -> T {
        match self {
            Self::Some(value) => value
            Self::None => default_func.call(())
        }
    }
}

impl<T> Option<T> where T: Default {
    pub fn unwrap_or_default(own self) -> T {
        match self {
            Self::Some(x) => x
            Self::None => T::default()
        }
    }
}

impl<T> Default for Option<T> {
    fn default() -> Self {
        Self::None
    }
}

impl Functor for Option {
    fn map<T, U, F: Fn<T, U>>(self: own Self<T>, _ func: F) -> Self<U> {
        match self {
